17	/**
18	 * Maps Owner & OwnerDto using Mapstruct
19	 */
20	@Mapper(uses = PetMapper.class, imports = {MembershipLevel.class, FiscalYear.class})
21	public interface OwnerMapper {
22	
23	    @Mapping(target = "selfLink",
24	            expression = "java(\"/api/owners/\" + owner.getId())")
25	    @Mapping(target = "displayName",
26	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
27	    @Mapping(target = "salutation",
