31	    @Mapping(target = "telephoneDisplay",
32	            expression = "java(TelephoneDisplay.of(owner.getTelephone()))")
33	    @Mapping(target = "membershipNumber",
34	            expression = "java(owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", FiscalYear.of(owner.getRegistrationDate()) % 100))")
35	    @Mapping(target = "fiscalYear",
36	            expression = "java(FiscalYear.label(owner.getRegistrationDate()))")
37	    @Mapping(target = "checkDigit",
38	            expression = "java(CheckDigit.of(owner.getCustomerCode()))")
39	    @Mapping(target = "membershipPoints",
40	            expression = "java(MembershipLevel.points(owner))")
41	    @Mapping(target = "membershipLevel",
42	            expression = "java(MembershipLevel.of(owner))")
43	    @Mapping(target = "locality",
44	            expression = "java(Locality.of(owner.getCustomerCode()))")
45	    @Mapping(target = "timezone",
46	            expression = "java(Timezone.of(Locality.of(owner.getCustomerCode())))")
47	    @Mapping(target = "contactPreference",
48	            expression = "java(ContactPreference.of(owner.getEmail()))")
49	    @Mapping(target = "ageBand",
50	            expression = "java(AgeBand.of(owner))")
51	    @Mapping(target = "ownerSegment",
52	            expression = "java(OwnerSegment.of(owner))")
53	    OwnerDto toOwnerDto(Owner owner);
54	
55	    Owner toOwner(OwnerDto ownerDto);
56	
57	    @Mapping(target = "id", ignore = true)
58	    @Mapping(target = "pets", ignore = true)
59	    Owner toOwner(OwnerFieldsDto ownerDto);
60	
61	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
62	
63	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
64	
65	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
66	        OwnerPageDto ownerPageDto = new OwnerPageDto();
67	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
68	        ownerPageDto.setPage(ownerPage.getNumber());
69	        ownerPageDto.setSize(ownerPage.getSize());
70	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
71	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
72	        return ownerPageDto;
