1	package org.springframework.samples.petclinic.mapper;
2	
3	/**
4	 * Derives an owner's {@code checkDigit}: a single Luhn check digit (0-9) computed over the
5	 * digits contained in the owner's {@code customerCode}, ignoring any non-digit characters.
6	 *
7	 * <p>Kept as a standalone helper (referenced from {@link OwnerMapper}'s {@code checkDigit}
8	 * expression) rather than a mapper {@code default} method: a {@code String}-to-{@code int}
9	 * method on the mapper interface would be picked up by MapStruct as an automatic conversion.
10	 */
11	final class CheckDigit {
12	
13	    private CheckDigit() {
14	    }
15	
16	    /**
17	     * The Luhn check digit over the digits in {@code customerCode}. Every digit is summed
18	     * right-to-left, doubling alternate digits (starting with the rightmost) and subtracting 9
19	     * from any doubled value over 9; the check digit makes that sum a multiple of 10.
20	     */
21	    static int of(String customerCode) {
22	        int sum = 0;
23	        boolean dbl = true;
24	        for (int i = customerCode.length() - 1; i >= 0; i--) {
25	            char c = customerCode.charAt(i);
26	            if (c < '0' || c > '9') {
27	                continue;
28	            }
29	            int d = c - '0';
30	            if (dbl) {
31	                d *= 2;
32	                if (d > 9) {
33	                    d -= 9;
34	                }
35	            }
36	            sum += d;
37	            dbl = !dbl;
38	        }
39	        return (10 - (sum % 10)) % 10;
40	    }
41	}
