3	import java.util.Set;
4	
5	import org.springframework.samples.petclinic.model.MembershipLevel;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.rest.dto.OwnerDto.OwnerSegmentEnum;
8	
9	/**
10	 * Derives an owner's marketing segment ('ownerSegment'), formatted {@code <TIER>_<AREA>}: one of
11	 * {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or
12	 * {@code STANDARD_REGIONAL}.
13	 *
14	 * <p>TIER is {@code PREMIUM} when the owner's {@link MembershipLevel#of(Owner) membershipLevel} is 3
15	 * or more, otherwise {@code STANDARD}. AREA is {@code METRO} when the owner's
16	 * {@link Locality#of(String) locality} is a known region (NSW, VIC or QLD), otherwise
17	 * {@code REGIONAL}.
18	 *
19	 * <p>Kept as a standalone helper (referenced from {@link OwnerMapper}'s {@code ownerSegment}
20	 * expression) rather than a mapper {@code default} method to avoid MapStruct picking it up as an
21	 * automatic conversion.
22	 */
23	final class OwnerSegment {
24	
25	    /** Regions that count as METRO. Anything else (including {@link Locality#UNKNOWN}) is REGIONAL. */
26	    private static final Set<String> METRO_REGIONS = Set.of("NSW", "VIC", "QLD");
27	
28	    /** Minimum membership level for the PREMIUM tier. */
29	    private static final int PREMIUM_MIN_LEVEL = 3;
30	
31	    private OwnerSegment() {
32	    }
33	
34	    /** The {@code <TIER>_<AREA>} segment for the given owner. */
35	    static OwnerSegmentEnum of(Owner owner) {
36	        String tier = MembershipLevel.of(owner) >= PREMIUM_MIN_LEVEL ? "PREMIUM" : "STANDARD";
37	        String area = METRO_REGIONS.contains(Locality.of(owner.getCustomerCode())) ? "METRO" : "REGIONAL";
38	        return OwnerSegmentEnum.fromValue(tier + "_" + area);
39	    }
40	}
