1	package org.springframework.samples.petclinic.mapper;
2	
3	/**
4	 * Derives an owner's canonical region ('locality') from its {@code customerCode}. Owner identity is
5	 * now {@code <REGION>-<HASH8>} (assigned at registration from the owner's postcode and a hash of its
6	 * telephone and last name), so the locality is simply the REGION component — the part before the
7	 * first {@code '-'}. It is {@code "UNKNOWN"} when no code has been assigned.
8	 *
9	 * <p>Kept as a standalone helper (referenced from {@link OwnerMapper}'s
10	 * {@code locality} expression) rather than a mapper {@code default} method: a
11	 * {@code String}-to-{@code String} method on the mapper interface would be
12	 * picked up by MapStruct as an automatic conversion for every String property.
13	 */
14	final class Locality {
15	
16	    static final String UNKNOWN = "UNKNOWN";
17	
18	    private Locality() {
19	    }
20	
21	    /**
22	     * The REGION component of the owner's {@code customerCode} — the text before the first
23	     * {@code '-'} — or {@code "UNKNOWN"} when the code is absent or carries no region prefix.
24	     */
25	    static String of(String customerCode) {
26	        if (customerCode == null) {
27	            return UNKNOWN;
28	        }
29	        int dash = customerCode.indexOf('-');
30	        if (dash <= 0) {
31	            return UNKNOWN;
32	        }
33	        return customerCode.substring(0, dash);
34	    }
35	}
