1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.util.HashSet;
6	import java.util.Map;
7	import java.util.Set;
8	
9	import net.officefloor.plugin.variable.Val;
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.repository.OwnerRepository;
12	
13	/**
14	 * Assigns the owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>} where REGION is the
15	 * region code derived from the owner's postcode (its inclusive range: {@code NSW 2000-2099},
16	 * {@code VIC 3000-3099}, {@code QLD 4000-4099}, else {@code UNKNOWN}) and HASH8 is the first 8
17	 * upper-case hex characters of {@code SHA-256} over the owner's normalized telephone concatenated
18	 * with its last name (e.g. {@code NSW-1A2B3C4D}).
19	 *
20	 * <p>The identity is derived deterministically from the owner's own fields — no sequence numbers —
21	 * so it does not depend on other owners or on creation order. The telephone has already been
22	 * normalized to E.164 form by {@link ValidateOwnerFields} before this step runs.
23	 *
24	 * <p>Should the deterministic code collide with an existing owner's {@code customerCode}, it is
25	 * de-duplicated by appending {@code -<n>} with the smallest {@code n} of 2 or more that makes it
26	 * unique (e.g. {@code NSW-1A2B3C4D}, then {@code NSW-1A2B3C4D-2}, {@code NSW-1A2B3C4D-3}, …).
27	 */
28	public class AssignCustomerCode {
29	
30	    /** Region -&gt; inclusive 4-digit postcode range {@code {low, high}}. */
31	    private static final Map<String, int[]> REGION_RANGE = Map.of(
32	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
33	
34	    private static final String UNKNOWN = "UNKNOWN";
35	
36	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
37	        String region = regionOf(owner.getPostcode());
38	        String hash8 = hash8(owner.getTelephone() + owner.getLastName());
39	        String base = region + "-" + hash8;
40	
41	        Set<String> taken = new HashSet<>();
42	        for (Owner existing : ownerRepository.findAll()) {
43	            if (existing.getCustomerCode() != null) {
44	                taken.add(existing.getCustomerCode());
45	            }
46	        }
47	
48	        String code = base;
49	        for (int n = 2; taken.contains(code); n++) {
50	            code = base + "-" + n;
51	        }
52	        owner.setCustomerCode(code);
53	    }
54	
55	    /** The region whose inclusive range contains {@code postcode}, or {@code UNKNOWN} when the
56	     *  postcode is absent, not four digits, or in no known range. */
57	    private static String regionOf(String postcode) {
58	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
59	            return UNKNOWN;
60	        }
61	        int value = Integer.parseInt(postcode);
62	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
63	            int[] range = entry.getValue();
64	            if (value >= range[0] && value <= range[1]) {
65	                return entry.getKey();
66	            }
67	        }
68	        return UNKNOWN;
69	    }
70	
71	    /** The first 8 upper-case hex characters (4 bytes) of {@code SHA-256(value)}. */
72	    private static String hash8(String value) {
73	        try {
74	            byte[] digest = MessageDigest.getInstance("SHA-256")
75	                    .digest(value.getBytes(StandardCharsets.UTF_8));
76	            StringBuilder sb = new StringBuilder(8);
77	            for (int i = 0; i < 4; i++) {
78	                sb.append(String.format("%02X", digest[i]));
79	            }
80	            return sb.toString();
81	        }
82	        catch (Exception ex) {
83	            throw new IllegalStateException("SHA-256 unavailable", ex);
84	        }
85	    }
86	}
