3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.slf4j.Logger;
7	import org.slf4j.LoggerFactory;
8	import org.springframework.samples.petclinic.model.FiscalYear;
9	import org.springframework.samples.petclinic.model.MembershipLevel;
10	import org.springframework.samples.petclinic.model.Owner;
11	
12	/**
13	 * Emits, on successful create via the dedicated {@code AUDIT} logger, both an audit line — carrying
14	 * the new owner's id, its {@code customerCode}, its {@code registrationDate}, its
15	 * {@code membershipLevel} and its {@code membershipNumber} — and an immutable structured
16	 * {@link OwnerCreatedEvent} rendered as JSON.
17	 *
18	 * <p>The event's {@code seq} is a process-wide monotonically increasing integer across creates, and
19	 * its identifier is the owner's {@link Owner#getPrimaryIdentifier() primary identifier} (the
20	 * customerCode today), so the event follows that identifier as it evolves.
21	 *
22	 * <p>Runs after {@link SaveOwner}, so the owner has been assigned its generated id, and before
23	 * {@link RespondWithOwnerCreated}, so both are written only once the create has succeeded.
24	 */
25	public class AuditOwnerCreated {
26	
27	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
28	
29	    /** Monotonically increasing event sequence, shared across all creates in this process. */
30	    private static final AtomicLong SEQUENCE = new AtomicLong();
31	
32	    public void service(@Val Owner owner) {
33	        AUDIT.info(
34	                "owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
35	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
36	                MembershipLevel.of(owner), membershipNumber(owner));
37	
38	        OwnerCreatedEvent event = new OwnerCreatedEvent(SEQUENCE.incrementAndGet(), owner.getId(),
39	                owner.getPrimaryIdentifier(), MembershipLevel.of(owner));
40	        AUDIT.info(event.toJson());
41	    }
42	
43	    private static String membershipNumber(Owner owner) {
44	        return owner.getCustomerCode() + "-M"
45	                + String.format("%02d", FiscalYear.of(owner.getRegistrationDate()) % 100);
46	    }
47	}
