1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Immutable structured audit event emitted once per successful owner create, rendered as the JSON
5	 * object {@code {seq, ownerId, customerCode, membershipLevel, event:'OWNER_CREATED'}}.
6	 *
7	 * <p>{@code seq} is a monotonically increasing integer across creates. {@code customerCode} carries
8	 * the owner's <em>current primary identifier</em> (see {@link
9	 * org.springframework.samples.petclinic.model.Owner#getPrimaryIdentifier()}); it is the customerCode
10	 * today and becomes the memberId once the two are unified, without any change here.
11	 *
12	 * <p>The record is immutable and self-serializing so the event cannot be mutated after it is built.
13	 */
14	public record OwnerCreatedEvent(long seq, int ownerId, String customerCode, int membershipLevel) {
15	
16	    /** The fixed discriminator carried by every owner-create event. */
17	    public static final String EVENT = "OWNER_CREATED";
18	
19	    /** Render this event as its canonical JSON object. */
20	    public String toJson() {
21	        return "{"
22	                + "\"seq\":" + this.seq + ","
23	                + "\"ownerId\":" + this.ownerId + ","
24	                + "\"customerCode\":" + quote(this.customerCode) + ","
25	                + "\"membershipLevel\":" + this.membershipLevel + ","
26	                + "\"event\":\"" + EVENT + "\""
27	                + "}";
28	    }
29	
30	    /** A JSON string literal for {@code value}, or {@code null} when absent. */
31	    private static String quote(String value) {
32	        if (value == null) {
33	            return "null";
34	        }
35	        StringBuilder sb = new StringBuilder(value.length() + 2).append('"');
36	        for (int i = 0; i < value.length(); i++) {
37	            char c = value.charAt(i);
38	            switch (c) {
39	                case '"' -> sb.append("\\\"");
40	                case '\\' -> sb.append("\\\\");
41	                case '\n' -> sb.append("\\n");
42	                case '\r' -> sb.append("\\r");
43	                case '\t' -> sb.append("\\t");
44	                default -> sb.append(c);
45	            }
46	        }
47	        return sb.append('"').toString();
48	    }
49	}
