1	package org.springframework.samples.petclinic.model;
2	
3	import java.time.LocalDate;
4	
5	/**
6	 * Fiscal-year arithmetic for date-derived owner values. The fiscal year starts on 1 July and is
7	 * named by the calendar year in which it ends, so a date in July–December belongs to the next
8	 * calendar year's fiscal year (e.g. 2025-08-10 → fiscal year 2026 → {@code FY26}) while a date in
9	 * January–June keeps the calendar year (e.g. 2026-03-01 → fiscal year 2026 → {@code FY26}).
10	 */
11	public final class FiscalYear {
12	
13	    /** First month (inclusive) of a new fiscal year. */
14	    private static final int FISCAL_YEAR_START_MONTH = 7;
15	
16	    private FiscalYear() {
17	    }
18	
19	    /** The fiscal year (starting 1 July) that {@code date} falls in. */
20	    public static int of(LocalDate date) {
21	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? date.getYear() + 1 : date.getYear();
22	    }
23	
24	    /** The fiscal-year label {@code FY<YY>} for {@code date}, YY being the last two digits. */
25	    public static String label(LocalDate date) {
26	        return String.format("FY%02d", of(date) % 100);
27	    }
28	}
