1	package org.springframework.samples.petclinic.model;
2	
3	import java.time.LocalDate;
4	
5	/**
6	 * Derives an owner's membership points and the numeric membership level bucketed from them.
7	 *
8	 * <p>Points start at {@code 0} and accumulate: {@code +2} when an email address is present;
9	 * {@code +1} when the owner has no namesakes ({@code namesakeCount} is {@code 0}); {@code +2} for a
10	 * household of {@code 3} or more members; {@code +3} for tenure of more than {@code 1} elapsed fiscal
11	 * year — the number of fiscal-year boundaries (1 July) between the owner's {@code registrationDate}
12	 * and today.
13	 *
14	 * <p>Points map to a level of {@code 1} ({@code 0}-{@code 1} points), {@code 2} ({@code 2}-{@code 3}),
15	 * {@code 3} ({@code 4}-{@code 5}) or {@code 4} ({@code 6} or more).
16	 */
17	public final class MembershipLevel {
18	
19	    /** Elapsed fiscal years that must be exceeded to earn the tenure points. */
20	    private static final long TENURE_FISCAL_YEARS_FOR_BONUS = 1;
21	
22	    /** Household size, in members, that must be reached to earn the household points. */
23	    private static final int HOUSEHOLD_SIZE_FOR_BONUS = 3;
24	
25	    private MembershipLevel() {
26	    }
27	
28	    /** Compute the membership points for the given owner. */
29	    public static int points(Owner owner) {
30	        int points = 0;
31	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
32	            points += 2;
33	        }
34	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
35	            points += 1;
36	        }
37	        if (owner.getHouseholdMemberCount() != null
38	                && owner.getHouseholdMemberCount() >= HOUSEHOLD_SIZE_FOR_BONUS) {
39	            points += 2;
40	        }
41	        if (tenureFiscalYears(owner) > TENURE_FISCAL_YEARS_FOR_BONUS) {
42	            points += 3;
43	        }
44	        return points;
45	    }
46	
47	    /** Bucket a points total into a membership level (1..4). */
48	    public static int levelForPoints(int points) {
49	        if (points >= 6) {
50	            return 4;
51	        }
52	        if (points >= 4) {
53	            return 3;
54	        }
55	        if (points >= 2) {
56	            return 2;
57	        }
58	        return 1;
59	    }
60	
61	    /** Compute the membership level (1..4) for the given owner, capped by the owner's
62	     *  {@code membershipLevelCap} when one is set. The cap is one above the maximum membership level
63	     *  among the owner's existing household members at creation (see
64	     *  {@link org.springframework.samples.petclinic.rest.function.owner.AssignMembershipLevelCap});
65	     *  when {@code null} the derived level applies unchanged. */
66	    public static int of(Owner owner) {
67	        int level = levelForPoints(points(owner));
68	        Integer cap = owner.getMembershipLevelCap();
69	        if (cap != null && level > cap) {
70	            return cap;
71	        }
72	        return level;
73	    }
74	
75	    /** Elapsed fiscal years (1 July boundaries) between the owner's {@code registrationDate} and
76	     *  today; {@code 0} when unknown. */
77	    private static long tenureFiscalYears(Owner owner) {
78	        LocalDate registrationDate = owner.getRegistrationDate();
79	        if (registrationDate == null) {
80	            return 0;
81	        }
82	        return FiscalYear.of(LocalDate.now()) - FiscalYear.of(registrationDate);
83	    }
84	}
